import{_ as a,o,c as r,ag as e,j as l}from"./chunks/framework.DoUXNnsN.js";const D=JSON.parse('{"title":"Docker","description":"","frontmatter":{"title":"Docker","aliases":["容器","容器化","Docker入门","Docker Engine","Docker Desktop"],"tags":["工具与工程","Docker","部署"],"status":"ai-draft","sources":["https://docs.docker.com/get-started/docker-overview/","https://docs.docker.com/reference/dockerfile/","https://learn.microsoft.com/en-us/dotnet/core/docker/build-container","https://learn.microsoft.com/en-us/sql/linux/sql-server-linux-docker-container-deployment","基于模型知识"],"updated":"2026-10-21T00:00:00.000Z","order":1},"headers":[],"relativePath":"50-工具与工程/Docker/Docker.md","filePath":"50-工具与工程/Docker/Docker.md"}'),d={name:"50-工具与工程/Docker/Docker.md"},i={style:{"overflow-x":"auto"}},n={viewBox:"0 0 760 150",style:{"min-width":"720px",width:"100%",height:"auto"},xmlns:"http://www.w3.org/2000/svg","font-family":"sans-serif","font-size":"14"};function c(s,t,h,p,k,u){return o(),r("div",null,[t[1]||(t[1]=e(`<blockquote class="callout-warn"><p>⚠ 未在本机运行验证：写本系列时，这台电脑<strong>没有安装 Docker</strong>，所以所有 <code>docker ...</code> 命令和&quot;容器里的输出&quot;都没有亲手跑过，内容以 Docker、Microsoft 官方文档为准（见 <code>sources</code>），已登记到待核对清单。本系列里<strong>能在本机验证的部分都验证过了</strong>：示例 .NET 程序用 <code>dotnet publish</code> 编译运行过，示例 Python 程序运行并用 curl 访问过，示例 YAML 用解析器检查过语法，MCR 上的镜像标签也查询过确实存在。你装好 Docker 后，请按各篇的&quot;动手实验&quot;自己跑一遍，如有出入以你机器上的实际输出为准。</p></blockquote><blockquote><p>本篇是 Docker 系列的<strong>总览页</strong>。读完你应该能：说清容器是什么、和虚拟机有什么区别；知道系列里每一篇讲什么、按什么顺序看；知道在工厂信息化（MES/WMS 一类系统）里 Docker 能帮你做什么。</p></blockquote><h2 id="一句话定义" tabindex="-1">一句话定义 <a class="header-anchor" href="#一句话定义" aria-label="Permalink to &quot;一句话定义&quot;">​</a></h2><p><strong>Docker</strong> 是把&quot;程序 + 它运行所需的一切（运行时、库、配置）&quot;打包成一个标准化的<strong>镜像</strong>，再用镜像在任何装了 Docker 的机器上启动出相互隔离的<strong>容器</strong>的工具。</p><h2 id="先修知识" tabindex="-1">先修知识 <a class="header-anchor" href="#先修知识" aria-label="Permalink to &quot;先修知识&quot;">​</a></h2><ul><li><a href="/Encyclopedia/10-计算机基础/操作系统/操作系统">操作系统</a>：知道&quot;进程&quot;是什么（一个正在运行的程序）。见 <a href="/Encyclopedia/10-计算机基础/操作系统/进程与线程">进程与线程</a>。</li><li><a href="/Encyclopedia/50-工具与工程/命令行与Linux">命令行与Linux</a>：Docker 几乎全靠命令行操作，至少会 <code>cd</code>、<code>ls</code>。</li><li><a href="/Encyclopedia/10-计算机基础/计算机网络/TCP-IP">TCP-IP</a>：知道&quot;端口&quot;是什么（一台电脑上用来区分不同服务的编号，如 SQL Server 默认 1433）。</li></ul><h2 id="它解决什么问题" tabindex="-1">它解决什么问题 <a class="header-anchor" href="#它解决什么问题" aria-label="Permalink to &quot;它解决什么问题&quot;">​</a></h2><p>先看一个每个做过项目的人都遇到过的场景。</p><p>你写了一个 .NET 小程序，在自己电脑上跑得好好的。交给同事，他说：&quot;我这报错，缺运行库。&quot;装完运行库，又说：&quot;数据库版本不对。&quot;再换到车间的服务器上，又是另一套环境。这类问题统称&quot;<strong>在我机器上能跑</strong>&quot;。</p><p>根源是：程序不只是你写的那几个文件，它还依赖<strong>环境</strong>——操作系统版本、.NET 或 Python 的版本、系统库、环境变量、端口……每台机器环境都不同。</p><p>Docker 的思路像<strong>集装箱</strong>：</p><ul><li>以前运货，每种货物（散装的米、整箱的电器、活的牲畜）都要为码头、卡车、轮船单独想办法；</li><li>后来大家约定一种标准钢箱，货物先装进箱里，码头、卡车、轮船只管搬&quot;箱子&quot;，不管里面是什么。</li></ul><p>Docker 里的&quot;箱子&quot;就是<strong>容器</strong>：程序和环境一起装进去，到哪都用同一种方式运行。</p><p>它在日常工作中最常见的几个用途：</p><table tabindex="0"><thead><tr><th>用途</th><th>例子</th></tr></thead><tbody><tr><td>快速搭环境</td><td>一条命令起一个 SQL Server、Redis，不用在电脑上装一堆软件；用完删掉，电脑保持干净</td></tr><tr><td>让开发、测试、生产环境一致</td><td>同一个镜像，三处运行</td></tr><tr><td>方便部署和回滚</td><td>新版本 = 换一个镜像标签；出问题换回旧标签</td></tr><tr><td>同一台机器跑多个互相冲突的版本</td><td>同时跑 SQL Server 2019 和 2022 两个容器，各占一个端口</td></tr></tbody></table><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><h3 id="容器不是虚拟机" tabindex="-1">容器不是虚拟机 <a class="header-anchor" href="#容器不是虚拟机" aria-label="Permalink to &quot;容器不是虚拟机&quot;">​</a></h3><p>虚拟机（VM，Virtual Machine）是在软件里&quot;模拟一整台电脑&quot;：每台虚拟机都有自己的完整操作系统，启动要几十秒到几分钟，占几个 GB。</p><p>容器则<strong>共用宿主机的操作系统内核</strong>，只是用内核提供的隔离功能（官方文档提到 Linux 的 namespaces 等）让每个容器&quot;以为&quot;自己独占了一套文件系统、进程列表和网络。所以容器启动通常是秒级，体积小得多。</p><table tabindex="0"><thead><tr><th></th><th>虚拟机</th><th>容器</th></tr></thead><tbody><tr><td>隔离方式</td><td>模拟整台硬件，各有完整操作系统</td><td>共用宿主机内核，隔离进程、文件系统、网络</td></tr><tr><td>启动速度</td><td>慢（启动一个操作系统）</td><td>快（本质是启动一个被隔离的进程）</td></tr><tr><td>体积</td><td>大（GB 级）</td><td>小（MB 级到几百 MB）</td></tr><tr><td>隔离强度</td><td>强</td><td>相对弱一些（共用内核）</td></tr></tbody></table><blockquote><p>在 Windows 上用 Docker Desktop 时，Linux 容器实际跑在一个轻量的 Linux 虚拟环境里（常见是 WSL 2）。这是 Docker Desktop 的实现细节，具体见官方文档，这里不展开。</p></blockquote><h3 id="五个必须分清的词" tabindex="-1">五个必须分清的词 <a class="header-anchor" href="#五个必须分清的词" aria-label="Permalink to &quot;五个必须分清的词&quot;">​</a></h3><table tabindex="0"><thead><tr><th>术语</th><th>一句话</th><th>类比</th></tr></thead><tbody><tr><td>镜像（Image）</td><td>只读的&quot;模板&quot;，包含程序和环境</td><td>软件安装光盘 / 类（class）</td></tr><tr><td>容器（Container）</td><td>镜像运行起来的实例</td><td>用光盘装好并正在运行的软件 / 对象（object）</td></tr><tr><td>仓库（Registry）</td><td>存放、分发镜像的服务，如 Docker Hub、微软的 MCR</td><td>应用商店</td></tr><tr><td>Dockerfile</td><td>写着&quot;怎么构建镜像&quot;的文本文件</td><td>菜谱</td></tr><tr><td>Compose</td><td>用一个 YAML 文件描述并同时启动多个容器</td><td>一份&quot;开席菜单&quot;</td></tr></tbody></table><p>Docker 本身分<strong>客户端</strong>（<code>docker</code> 命令，你敲的）和<strong>守护进程</strong>（<code>dockerd</code>，在后台真正干活，管理镜像、容器、网络、数据卷），两者通过 API 通信。所以如果你敲 <code>docker ps</code> 报&quot;连不上 daemon&quot;，通常是 Docker Desktop 没启动。</p><h3 id="入门路径-系列阅读顺序" tabindex="-1">入门路径（系列阅读顺序） <a class="header-anchor" href="#入门路径-系列阅读顺序" aria-label="Permalink to &quot;入门路径（系列阅读顺序）&quot;">​</a></h3><ol><li><a href="/Encyclopedia/50-工具与工程/Docker/Docker镜像与容器">Docker镜像与容器</a>：先搞懂镜像、容器、数据卷、端口映射，会用 <code>docker run</code> 等基本命令。</li><li><a href="/Encyclopedia/50-工具与工程/Docker/Dockerfile">Dockerfile</a>：学会自己把 .NET 或 Python 程序打包成镜像。</li><li><a href="/Encyclopedia/50-工具与工程/Docker/Docker-Compose">Docker-Compose</a>：用一个文件同时启动&quot;SQL Server + 你的应用&quot;。</li></ol><p>学完整个系列，你就能做到：&quot;新同事拿到代码，一条 <code>docker compose up</code> 就把数据库和应用都跑起来&quot;。</p><h2 id="逐步例子-一次完整流程的全景" tabindex="-1">逐步例子：一次完整流程的全景 <a class="header-anchor" href="#逐步例子-一次完整流程的全景" aria-label="Permalink to &quot;逐步例子：一次完整流程的全景&quot;">​</a></h2><p>下面是官方 .NET 教程里&quot;从代码到容器&quot;的流程（命令引自官方文档，<strong>⚠ 未在本机运行验证</strong>）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 写代码        Program.cs</span></span>
<span class="line"><span>② 发布          dotnet publish -c Release         -&gt; 得到一堆编译好的文件</span></span>
<span class="line"><span>③ 写 Dockerfile  FROM / COPY / ENTRYPOINT</span></span>
<span class="line"><span>④ 构建镜像      docker build -t counter-image .</span></span>
<span class="line"><span>⑤ 运行容器      docker run -it --rm counter-image</span></span></code></pre></div><p>其中 ② 在本机验证过（后面 <a href="/Encyclopedia/50-工具与工程/Docker/Dockerfile">Dockerfile</a> 里有具体输出），③④⑤ 需要 Docker。整个过程的数据流：</p>`,31)),l("div",i,[(o(),r("svg",n,[...t[0]||(t[0]=[e('<defs><marker id="dk-arr" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto"><path d="M0,0 L10,5 L0,10 z" fill="currentColor"></path></marker></defs><rect x="10" y="40" width="130" height="60" rx="8" fill="currentColor" fill-opacity="0.08" stroke="currentColor"></rect><text x="75" y="66" text-anchor="middle" fill="currentColor">Dockerfile</text><text x="75" y="86" text-anchor="middle" fill="currentColor" font-size="12">+ 你的代码</text><rect x="210" y="40" width="130" height="60" rx="8" fill="currentColor" fill-opacity="0.15" stroke="currentColor"></rect><text x="275" y="66" text-anchor="middle" fill="currentColor">镜像 Image</text><text x="275" y="86" text-anchor="middle" fill="currentColor" font-size="12">只读模板</text><rect x="410" y="40" width="130" height="60" rx="8" fill="currentColor" fill-opacity="0.25" stroke="currentColor"></rect><text x="475" y="66" text-anchor="middle" fill="currentColor">容器 Container</text><text x="475" y="86" text-anchor="middle" fill="currentColor" font-size="12">运行中的实例</text><rect x="610" y="40" width="130" height="60" rx="8" fill="currentColor" fill-opacity="0.08" stroke="currentColor"></rect><text x="675" y="66" text-anchor="middle" fill="currentColor">仓库 Registry</text><text x="675" y="86" text-anchor="middle" fill="currentColor" font-size="12">Docker Hub / MCR</text><line x1="140" y1="70" x2="208" y2="70" stroke="currentColor" marker-end="url(#dk-arr)"></line><text x="174" y="60" text-anchor="middle" fill="currentColor" font-size="12">build</text><line x1="340" y1="70" x2="408" y2="70" stroke="currentColor" marker-end="url(#dk-arr)"></line><text x="374" y="60" text-anchor="middle" fill="currentColor" font-size="12">run</text><path d="M610,110 Q430,150 275,102" fill="none" stroke="currentColor" stroke-dasharray="4 3" marker-end="url(#dk-arr)"></path><text x="450" y="140" text-anchor="middle" fill="currentColor" font-size="12">pull（下载镜像）</text>',19)])]))]),t[2]||(t[2]=e(`<h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><p>装好 Docker Desktop（Windows）后，打开 PowerShell 做下面三步（<strong>⚠ 未在本机运行验证</strong>）：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">docker version            </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 同时显示 Client 和 Server 两段信息；只有 Client 说明守护进程没启动</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">docker run hello</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">world    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 官方的&quot;冒烟测试&quot;镜像：下载并运行，打印一段欢迎信息后退出</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">docker ps </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">a              </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 列出所有容器（包括已退出的），应该能看到刚才的 hello-world</span></span></code></pre></div><p>看到欢迎信息就说明：客户端、守护进程、仓库下载、容器运行整条链路都通了。最后用 <code>docker rm &lt;容器名或ID&gt;</code> 清理。</p><h2 id="常见坑与排查" tabindex="-1">常见坑与排查 <a class="header-anchor" href="#常见坑与排查" aria-label="Permalink to &quot;常见坑与排查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>常见原因</th><th>办法</th></tr></thead><tbody><tr><td><code>Cannot connect to the Docker daemon</code></td><td>Docker Desktop 没启动</td><td>先启动 Docker Desktop，等它状态变成 running</td></tr><tr><td>镜像下载很慢或超时</td><td>访问境外仓库网络差；本机设了代理变量</td><td>给 Docker 配代理或镜像加速（见各自的官方文档）；注意 <a href="/Encyclopedia/50-工具与工程/环境变量与PATH">环境变量与PATH</a> 里讲的代理变量对 Docker 守护进程不一定生效</td></tr><tr><td>在公司服务器上&quot;装不了&quot;</td><td>生产环境常有安全与审批要求</td><td>先和运维确认策略，别自己在生产机器上乱装</td></tr><tr><td>把数据库放容器里，删容器后数据没了</td><td>没有挂数据卷</td><td>见 <a href="/Encyclopedia/50-工具与工程/Docker/Docker镜像与容器">Docker镜像与容器</a> 的&quot;数据卷&quot;一节</td></tr></tbody></table><h2 id="业务视角与技术视角" tabindex="-1">业务视角与技术视角 <a class="header-anchor" href="#业务视角与技术视角" aria-label="Permalink to &quot;业务视角与技术视角&quot;">​</a></h2><ul><li><strong>业务视角</strong>：工厂的 MES、WMS、QMS 一类系统往往要在开发、测试、客户现场反复部署。容器化的价值是<strong>部署可重复</strong>：同一个镜像在测试环境验证通过，生产环境用同一个镜像，减少&quot;现场装不起来&quot;。但很多工厂现场仍是 Windows Server + IIS 的部署方式（见 <a href="/Encyclopedia/30-.NET生态/部署到IIS">部署到IIS</a>），是否上容器要结合运维能力判断，别为了新而新。</li><li><strong>技术视角</strong>：.NET 程序通常用&quot;多阶段构建&quot;生成很小的运行镜像（见 <a href="/Encyclopedia/50-工具与工程/Docker/Dockerfile">Dockerfile</a>）；数据库用官方镜像加数据卷（见 <a href="/Encyclopedia/50-工具与工程/Docker/Docker-Compose">Docker-Compose</a>）；持续集成里用容器统一构建环境（见 <a href="/Encyclopedia/50-工具与工程/CI-CD">CI-CD</a>）。</li></ul><h2 id="练习题与答案" tabindex="-1">练习题与答案 <a class="header-anchor" href="#练习题与答案" aria-label="Permalink to &quot;练习题与答案&quot;">​</a></h2><p><strong>1.</strong> 用自己的话说：镜像和容器是什么关系？</p><p>答：镜像是只读模板，容器是用镜像启动出来的运行实例。一个镜像可以启动多个互相独立的容器，就像一份光盘可以装到多台电脑上。</p><p><strong>2.</strong> 容器启动为什么通常比虚拟机快？</p><p>答：容器不需要启动完整的操作系统，它只是宿主机上一个被隔离的进程，共用宿主机的内核。</p><p><strong>3.</strong> 同事说&quot;我这能跑，你那不行&quot;，用 Docker 怎么解决？</p><p>答：把程序和运行环境一起打成镜像，双方都用同一个镜像启动容器，环境就一致了。</p><p><strong>4.</strong> <code>docker ps</code> 报连不上 daemon，先查什么？</p><p>答：Docker Desktop（守护进程）是否已启动。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Docker 把程序和环境打成<strong>镜像</strong>，用镜像启动<strong>容器</strong>；容器共用宿主机内核，轻量、快。</li><li>客户端 <code>docker</code> 命令与后台守护进程 <code>dockerd</code> 分工；镜像存放在<strong>仓库</strong>。</li><li>系列路径：<a href="/Encyclopedia/50-工具与工程/Docker/Docker镜像与容器">Docker镜像与容器</a> → <a href="/Encyclopedia/50-工具与工程/Docker/Dockerfile">Dockerfile</a> → <a href="/Encyclopedia/50-工具与工程/Docker/Docker-Compose">Docker-Compose</a>。</li><li>本系列的 Docker 命令均未在本机运行，请以官方文档和你机器上的实际结果为准。</li></ul><h2 id="相关词条" tabindex="-1">相关词条 <a class="header-anchor" href="#相关词条" aria-label="Permalink to &quot;相关词条&quot;">​</a></h2><p><a href="/Encyclopedia/50-工具与工程/Docker/Docker镜像与容器">Docker镜像与容器</a>、<a href="/Encyclopedia/50-工具与工程/Docker/Dockerfile">Dockerfile</a>、<a href="/Encyclopedia/50-工具与工程/Docker/Docker-Compose">Docker-Compose</a>、<a href="/Encyclopedia/50-工具与工程/命令行与Linux">命令行与Linux</a>、<a href="/Encyclopedia/50-工具与工程/环境变量与PATH">环境变量与PATH</a>、<a href="/Encyclopedia/50-工具与工程/CI-CD">CI-CD</a>、<a href="/Encyclopedia/40-数据库/SQL-Server/SQL-Server">SQL-Server</a>、<a href="/Encyclopedia/30-.NET生态/dotNET运行时与SDK">dotNET运行时与SDK</a></p><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li>Docker 概览：<a href="https://docs.docker.com/get-started/docker-overview/" target="_blank" rel="noreferrer">https://docs.docker.com/get-started/docker-overview/</a></li><li>官方 .NET 容器化教程：<a href="https://learn.microsoft.com/en-us/dotnet/core/docker/build-container" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/dotnet/core/docker/build-container</a></li><li>在容器里运行 SQL Server：<a href="https://learn.microsoft.com/en-us/sql/linux/sql-server-linux-docker-container-deployment" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/sql/linux/sql-server-linux-docker-container-deployment</a></li></ul>`,23))])}const g=a(d,[["render",c]]);export{D as __pageData,g as default};
